<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Validator};
use App\Support\{Access,Amount,Audit};
use App\Services\DocumentService;
class OperationsController {
 const MODULES=['manufacturing','restaurant','services','projects','assets','cheques'];
 public function index(Request $r,string $module){$this->guard($r,$module);return Access::scope(DB::table('records'),$r->user())->where('module',$module)->orderByDesc('id')->paginate(50);}
 private function guard(Request $r,string $module): void {abort_unless(in_array($module,self::MODULES),404);Access::require($r->user(),in_array($module,['assets','cheques'])?'accounting':'view');$modules=json_decode(DB::table('business')->value('modules'),true);abort_unless($module==='cheques'||in_array($module,$modules),422,'Enable this module in settings.');}
 public function save(Request $r,string $module,?int $id=null){$this->guard($r,$module);Access::require($r->user(),'create');$v=$r->validate(['branch_id'=>'required|integer|exists:branches,id','name'=>'required|string|max:150','status'=>'required|in:open,in_progress,ready,completed,cancelled','data'=>'required|array','version'=>'nullable|integer','reason'=>'nullable|string|max:1000']);Access::branch($r->user(),(int)$v['branch_id']);
  $rules=match($module){
   'manufacturing'=>['output_product_id'=>'required|integer|exists:products,id','output_quantity'=>'required|numeric|gt:0','components'=>'required|array|min:1','components.*.product_id'=>'required|integer|exists:products,id','components.*.quantity'=>'required|numeric|gt:0','warehouse_id'=>'required|integer|exists:warehouses,id'],
   'restaurant'=>['table'=>'required|string|max:30','order_notes'=>'nullable|string|max:2000','items'=>'required|array|min:1','items.*.product_id'=>'required|integer|exists:products,id','items.*.quantity'=>'required|numeric|gt:0','invoice_id'=>'nullable|integer|exists:documents,id'],
   'services'=>['party_id'=>'required|integer|exists:parties,id','description'=>'required|string|max:4000','assigned_to'=>'nullable|string|max:150','due_date'=>'nullable|date_format:Y-m-d','invoice_id'=>'nullable|integer|exists:documents,id'],
   'projects'=>['party_id'=>'required|integer|exists:parties,id','budget'=>'required|numeric|min:0','milestones'=>'nullable|string|max:4000','document_ids'=>'nullable|array','document_ids.*'=>'integer|exists:documents,id'],
   'assets'=>['purchase_date'=>'required|date_format:Y-m-d','cost'=>'required|numeric|gt:0','salvage'=>'required|numeric|min:0','life_months'=>'required|integer|min:1|max:1200','last_depreciation'=>'nullable|date_format:Y-m','acquisition_document_id'=>'required|integer|exists:documents,id'],
   'cheques'=>['number'=>'required|string|max:80','date'=>'required|date_format:Y-m-d','amount'=>'required|numeric|gt:0','direction'=>'required|in:received,issued','party_id'=>'required|integer|exists:parties,id','state'=>'required|in:held,deposited,cleared,bounced,cancelled','document_id'=>'nullable|integer|exists:documents,id'],
  };$data=Validator::make($v['data'],$rules)->validate();
  if(!empty($data['warehouse_id'])){ $warehouse=DB::table('warehouses')->find($data['warehouse_id']);abort_unless($warehouse->branch_id==(int)$v['branch_id'],422,'Warehouse belongs to a different branch.'); }if($module==='assets'&&Amount::parse($data['salvage'])>Amount::parse($data['cost']))abort(422,'Salvage cannot exceed cost.');
  $refs=array_filter([$data['invoice_id']??null,$data['document_id']??null,$data['acquisition_document_id']??null,...($data['document_ids']??[])]);
  foreach($refs as $ref){$d=DB::table('documents')->find($ref);abort_unless($d->branch_id==(int)$v['branch_id'],422,'Linked document belongs to another branch.');}
  return DB::transaction(function()use($v,$module,$id,$data,$r){$before=$id?DB::table('records')->lockForUpdate()->find($id):null;if($id){abort_unless($before&&$before->module===$module,404);Access::branch($r->user(),$before->branch_id);abort_unless($before->version===($v['version']??0),409,'Record changed. Reload.');}
   if($module==='manufacturing'&&$before&&$before->status==='completed')abort(422,'Completed production orders are locked.');if($module==='manufacturing'&&!$before&&$v['status']==='completed')abort(422,'Use Produce to complete a manufacturing order.');if($module==='assets'&&$before){$old=json_decode($before->data,true);$data['last_depreciation']=$old['last_depreciation']??null;$data['depreciated_paise']=$old['depreciated_paise']??0;if($data['depreciated_paise']>0)foreach(['cost','salvage','life_months','purchase_date']as $key)abort_if($old[$key]!=$data[$key],422,'Asset basis cannot change after depreciation.');}
   elseif($module==='assets'){unset($data['last_depreciation']);$data['depreciated_paise']=0;}
   $row=['branch_id'=>$v['branch_id'],'module'=>$module,'name'=>$v['name'],'status'=>$v['status'],'data'=>json_encode($data),'version'=>($before->version??0)+1,'updated_at'=>now()];if($id)DB::table('records')->where('id',$id)->update($row);else{$row['created_at']=now();$id=DB::table('records')->insertGetId($row);}Audit::record($r->user()->id,'operation_save','records',$id,$before,$row,$v['reason']??'',(int)$v['branch_id']);return ['id'=>$id];});
 }
 public function manufacture(Request $r,int $id,DocumentService $svc){$this->guard($r,'manufacturing');Access::require($r->user(),'accounting');$v=$r->validate(['date'=>'required|date_format:Y-m-d']);return DB::transaction(function()use($id,$r,$svc,$v){$record=DB::table('records')->lockForUpdate()->find($id);abort_unless($record&&$record->module==='manufacturing',404);Access::branch($r->user(),$record->branch_id);abort_if($record->status==='completed',422,'This order has already been completed.');$data=json_decode($record->data,true);$lines=[];
  foreach($data['components']as $c)$lines[]=['product_id'=>$c['product_id'],'quantity'=>'-'.$c['quantity'],'price'=>'0'];$lines[]=['product_id'=>$data['output_product_id'],'quantity'=>$data['output_quantity'],'price'=>'0'];$doc=$svc->save(['kind'=>'production','date'=>$v['date'],'branch_id'=>$record->branch_id,'warehouse_id'=>$data['warehouse_id'],'tax_treatment'=>'non_gst','reason'=>'Production order '.$id,'state_code'=>'32','price_tier'=>'retail','lines'=>$lines],$r->user());$svc->post($doc,$r->user());$data['document_id']=$doc;DB::table('records')->where('id',$id)->update(['status'=>'completed','data'=>json_encode($data),'version'=>$record->version+1,'updated_at'=>now()]);Audit::record($r->user()->id,'manufacture','records',$id,$record,['document_id'=>$doc],'',$record->branch_id);return ['id'=>$doc];});}
 public function depreciate(Request $r,int $id,DocumentService $svc){Access::require($r->user(),'accounting');Access::require($r->user(),'approve');$v=$r->validate(['month'=>'required|date_format:Y-m']);return DB::transaction(function()use($r,$id,$svc,$v){$biz=DB::table('business')->lockForUpdate()->first();$record=DB::table('records')->lockForUpdate()->find($id);abort_unless($record&&$record->module==='assets',404);Access::branch($r->user(),$record->branch_id);$data=json_decode($record->data,true);$month=$v['month'];$date=\Carbon\Carbon::createFromFormat('Y-m-d',$month.'-01')->endOfMonth()->toDateString();
  abort_if($biz->locked_until&&$date<=$biz->locked_until,422,'Period locked.');abort_if($month<substr($data['purchase_date'],0,7)||($data['last_depreciation']??'')>=$month,422,'Invalid or already depreciated month.');
  $expected=isset($data['last_depreciation'])?\Carbon\Carbon::parse($data['last_depreciation'].'-01')->addMonth()->format('Y-m'):substr($data['purchase_date'],0,7);abort_unless($month===$expected,422,'Post depreciation sequentially from '.$expected);
  $base=Amount::parse($data['cost'])-Amount::parse($data['salvage']);$charge=min($base-($data['depreciated_paise']??0),Amount::divide($base,(int)$data['life_months']));abort_if($charge<=0,422,'Asset is fully depreciated.');
  $d=$this->systemDocument('depreciation',$record->branch_id,$date,$r->user()->id,$charge);$svc->entry($d,'5300',$charge);$svc->entry($d,'1410',-$charge);$svc->assertBalanced($d->id);$data['depreciated_paise']=($data['depreciated_paise']??0)+$charge;$data['last_depreciation']=$month;DB::table('records')->where('id',$id)->update(['data'=>json_encode($data),'version'=>$record->version+1,'updated_at'=>now()]);Audit::record($r->user()->id,'depreciate','records',$id,$record,['data'=>$data,'document_id'=>$d->id],'',$record->branch_id);return ['id'=>$d->id];});}
 public function systemDocument(string $kind,int $branch,string $date,int $user,int $total): object {
  $biz=DB::table('business')->first();$id=DB::table('documents')->insertGetId(['kind'=>$kind,'status'=>'posted','date'=>$date,'branch_id'=>$branch,'created_by'=>$user,'posted_by'=>$user,'posted_at'=>now(),'total_paise'=>$total,'net_paise'=>$total,'business_snapshot'=>json_encode($biz),'created_at'=>now(),'updated_at'=>now()]);DB::table('documents')->where('id',$id)->update(['number'=>strtoupper($kind).'-'.$id]);return DB::table('documents')->find($id);
 }
 public function bank(Request $r){Access::require($r->user(),'accounting');return Access::scope(DB::table('bank_lines'),$r->user())->orderByDesc('id')->paginate(100);}
 public function bankSave(Request $r){Access::require($r->user(),'accounting');$v=$r->validate(['branch_id'=>'required|integer|exists:branches,id','account_id'=>'required|integer|exists:accounts,id','date'=>'required|date_format:Y-m-d','reference'=>'required|string|max:150','amount'=>'required|numeric']);Access::branch($r->user(),(int)$v['branch_id']);abort_unless(DB::table('accounts')->where('id',$v['account_id'])->value('type')==='asset',422);$v['amount_paise']=Amount::parse($v['amount']);unset($v['amount']);$v['created_at']=now();$v['updated_at']=now();$id=DB::transaction(function()use($v,$r){$id=DB::table('bank_lines')->insertGetId($v);Audit::record($r->user()->id,'bank_import','bank_lines',$id,null,$v,'',$v['branch_id']);return $id;});return ['id'=>$id];}
 public function reconcile(Request $r,int $id){Access::require($r->user(),'accounting');$v=$r->validate(['ledger_entry_id'=>'nullable|integer|exists:ledger_entries,id','reason'=>'required|string|min:3|max:1000']);return DB::transaction(function()use($r,$id,$v){$b=DB::table('bank_lines')->lockForUpdate()->find($id);abort_unless($b,404);Access::branch($r->user(),$b->branch_id);if($v['ledger_entry_id']){$l=DB::table('ledger_entries')->find($v['ledger_entry_id']);abort_unless($l->branch_id===$b->branch_id&&$l->account_id===$b->account_id&&$l->debit_paise-$l->credit_paise===$b->amount_paise,422,'Account, branch and signed amount must match.');}DB::table('bank_lines')->where('id',$id)->update(['ledger_entry_id'=>$v['ledger_entry_id'],'updated_at'=>now()]);Audit::record($r->user()->id,'reconcile','bank_lines',$id,$b,$v,$v['reason'],$b->branch_id);return ['ok'=>true];});}
}
